// One use case per action, "because Clean Architecture"
class GetThemeModeUseCase {
  GetThemeModeUseCase(this._settings);
  final SettingsRepository _settings;

  // A class, a constructor parameter and a test fake. No logic.
  Future<ThemeMode> call() => _settings.themeMode();
}

class SettingsViewModel extends ChangeNotifier {
  SettingsViewModel(this._getThemeMode);
  final GetThemeModeUseCase _getThemeMode;
  ThemeMode mode = ThemeMode.system;

  Future<void> load() async {
    mode = await _getThemeMode();
    notifyListeners();
  }
}

// Simple feature: the view model talks to the repository
class SettingsViewModel extends ChangeNotifier {
  SettingsViewModel(this._settings);
  final SettingsRepository _settings;
  ThemeMode mode = ThemeMode.system;

  Future<void> load() async {
    mode = await _settings.themeMode();
