  }
}

// A use case that earns its place: two repositories, two screens
class BookTripUseCase {
  BookTripUseCase(this._trips, this._payments);
  final TripRepository _trips;
  final PaymentRepository _payments;

  Future<void> call(Trip trip) async {
    final receipt = await _payments.charge(trip.price);
    await _trips.confirm(trip, receipt);
  }
}
